# region: fold
def fold(raw):
    out = []
    for tok in raw:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: digest
def digest(xs):
    return [v for v in xs if v % 2 == 0]

# region: sift
def sift(xs, cut=8):
    lo = [v for v in xs if v < cut]
    hi = [v for v in xs if v > cut]
    return {'n': len(xs), 'lo': len(lo), 'hi': len(hi)}

# region: emit
def emit(summary, bar=2):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return emit(sift(digest(fold(raw))))

